import{c as a,Q as t,j as e,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"MPAC: A Multi-Principal Agent Coordination Protocol for Interoperable Multi-Agent Collaboration","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.09744","title":"MPAC: A Multi-Principal Agent Coordination Protocol for Interoperable Multi-Agent Collaboration","archived_date":"2026-07-31T00:00:00.000Z","arxiv_id":2604.09744,"authors":["Kaiyang Qian","Xinmin Fang","Zhengxiong Li"],"collected_at":"2026-07-31T00:00:00.000Z","collected_by":"routine-d","domain":"multi-agent","pdf_path":"pdfs/2604.09744.pdf","published_date":"2026-04-10T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-10-mpac-multi-principal-agent-coordination-protocol-2604-09744.md","filePath":"research/papers/2026-04-10-mpac-multi-principal-agent-coordination-protocol-2604-09744.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-04-10-mpac-multi-principal-agent-coordination-protocol-2604-09744.md"};function n(l,o,c,p,d,s){return t(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="mpac-a-multi-principal-agent-coordination-protocol-for-interoperable-multi-agent-collaboration" tabindex="-1">MPAC: A Multi-Principal Agent Coordination Protocol for Interoperable Multi-Agent Collaboration <a class="header-anchor" href="#mpac-a-multi-principal-agent-coordination-protocol-for-interoperable-multi-agent-collaboration" aria-label="Permalink to &quot;MPAC: A Multi-Principal Agent Coordination Protocol for Interoperable Multi-Agent Collaboration&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>現有多代理協定多假設單一擁有者，MPAC 針對「跨組織代理需共享資源協作」的場景設計，提出五層架構與「顯式協調語意」（explicit coordination semantics），把衝突視為結構化物件並保留人工裁決選項。實作涵蓋 21 種訊息型別、狀態機、因果排序機制與並行控制，並提供 Python/TypeScript 兩版開源實作。基準測試顯示協調開銷降低 95%、相較序列化基線加速 4.8 倍——此加速來自協調層本身，非代理個別推理速度提升。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>MPAC 把「衝突」明確建模為結構化物件並保留人工裁決通道，呼應本 repo <code>core.md §PROPOSE 委派</code>（原 <code>graph.md</code>） 中「多 agent 矛盾上呈裁決者，child 不 self-resolve」的設計原則；其把協調語意獨立於個別代理推理之外的分層做法，也是 <code>core.md §PROPOSE 委派</code>「邊只存在於資料真的流動之處」的具體實踐參考。</p>',5)])])}const h=a(i,[["render",n]]);export{u as __pageData,h as default};
